def publish_directory_once(working: Path, destination: Path) -> None:
    """Publish one private directory through the shared immutable primitive."""

    try:
        publish_directory_no_replace(working, destination)
    except FileExistsError as error:
        raise ImmutablePublicationError(f"refusing to replace immutable directory: {destination}") from error
    except BlockingIOError as error:
        raise ImmutablePublicationError(f"publication is already in progress for: {destination}") from error
    except (ArtifactVerificationError, MemberSourceError, OSError, ValueError) as error:
        raise ImmutablePublicationError(f"immutable directory publication failed for {destination}: {error}") from error

