def _raw_schema(
    *,
    schema_id: str,
    collection: str,
    attributes: Mapping[str, Any],
    required_attributes: Sequence[str],
) -> dict[str, Any]:
    return {
        "$id": schema_id,
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "additionalProperties": False,
        "properties": {
            "data": {
                "additionalProperties": False,
                "properties": {
                    "attributes": {
                        "additionalProperties": False,
                        "properties": dict(attributes),
                        "required": list(required_attributes),
                        "type": "object",
                    },
                    "id": {"minLength": 1, "type": "string"},
                    "links": _LINKS_SCHEMA,
                    "relationships": _RELATIONSHIPS_SCHEMA,
                    "type": {"const": collection},
                },
                "required": ["attributes", "id", "type"],
                "type": "object",
            },
            "included": _INCLUDED_SCHEMA,
            "meta": _META_SCHEMA,
        },
        "required": ["data"],
        "type": "object",
        "x-spicy-record-order": [
            {
                "fieldPath": "/data/id",
                "nullOrder": "forbidden",
                "tupleComparison": "utf16-code-unit",
                "valueType": "string",
            }
        ],
    }

